text:
.bubble {
  --tooltip-green: var(--color-tooltip-tooltip-green-1);
  --tooltip-yellow: var(--status-warning-text);
  --tooltip-pink: var(--color-tooltip-tooltip-pink-2);
  animation: appear 100ms ease-out;
}
:global([data-theme="dark"]) .bubble {
  --tooltip-green: var(--color-tooltip-tooltip-green-5);
  --tooltip-yellow: var(--color-tooltip-tooltip-yellow-6);
  --tooltip-pink: var(--color-tooltip-tooltip-pink-7);
  background: var(--color-tooltip-background-8);
  color: var(--color-tooltip-color-9);
  --body: var(--color-tooltip-body-10);
  --link: var(--color-tooltip-link-11);
}
.bubble a {
  color: var(--link);
  text-decoration: underline;
}
.bubble :focus-visible,
.info:focus-visible {
  outline: 2px solid var(--color-tooltip-tooltip-pink-7);
  outline-offset: 2px;
}
@keyframes appear {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@media (prefers-reduced-motion: reduce) {
  .bubble {
    animation: none;
  }
}

:global(html[data-workspace][data-appearance="vercel"]) .bubble {
  --tooltip-green: var(--status-success-text);
  --tooltip-yellow: var(--warning);
  --tooltip-pink: var(--appearance-link);
  --body: var(--muted-foreground);
  --link: var(--appearance-link);
  background: var(--card);
  color: var(--foreground);
  border-color: var(--border);
  border-radius: var(--appearance-control-radius);
  box-shadow: 0 4px 16px var(--color-tooltip-box-shadow-13);
}
:global(html[data-workspace][data-appearance="vercel"])
  :is(.bubble, .info):focus-visible {
  outline-color: var(--ring);
}
:global(html[data-workspace][data-appearance="vercel"]) .info {
  border-color: var(--border-hover);
}
:global(html[data-workspace][data-appearance="vercel"]) .info:hover,
:global(html[data-workspace][data-appearance="vercel"])
  .info[aria-expanded="true"] {
  background: var(--highlight-background);
  border-color: var(--highlight-border);
  color: var(--highlight-foreground);
}
:global(html[data-workspace][data-appearance="vercel"]) .bubble :focus-visible {
  outline-color: var(--ring);
}

:global(html[data-workspace][data-appearance="vercel"]) button.info {
  border-radius: 50%;
}
